create table private.taipei_abcd_draft_versions (
 id uuid primary key default gen_random_uuid(),
 organization_id uuid not null, branch_id uuid not null, client_id uuid not null,
 form text not null check(form in ('A','B','C')),
 usage_year integer not null check(usage_year=115),
 month integer not null check(month between 0 and 12),
 template_key text not null check(template_key='taipei.daycare.abcd.115.114-11.draft-v1'),
 source_revision text not null check(source_revision='114.11'),
 source_sha256 text not null check(source_sha256='64bb716b19362580295fe8ee2e452d32e82d6f3c67773d5956f66c7e17d3c481'),
 publication_status text not null default 'pending_approval' check(publication_status='pending_approval'),
 state text not null default 'draft' check(state='draft'),
 version integer not null check(version>0),
 previous_version_id uuid references private.taipei_abcd_draft_versions(id) on delete restrict,
 answers jsonb not null check(jsonb_typeof(answers)='object'),
 source_snapshot jsonb,
 content_hash text not null check(content_hash ~ '^[a-f0-9]{64}$'),
 actor_user_id uuid not null references auth.users(id) on delete restrict,
 created_at timestamptz not null default clock_timestamp(),
 foreign key(client_id,organization_id,branch_id) references public.clients(id,organization_id,branch_id) on delete restrict,
 unique(organization_id,branch_id,client_id,form,usage_year,month,version),
 unique(previous_version_id),
 check((form='C' and month between 1 and 12 and jsonb_typeof(source_snapshot)='object') or
   (form in ('A','B') and month=0 and source_snapshot is null)),
 check((version=1 and previous_version_id is null) or(version>1 and previous_version_id is not null))
);
create index taipei_abcd_client_idx on private.taipei_abcd_draft_versions(client_id,form,usage_year,month,version desc);
create index taipei_abcd_actor_idx on private.taipei_abcd_draft_versions(actor_user_id);
create table private.taipei_abcd_draft_operations (
 actor_user_id uuid not null references auth.users(id) on delete restrict,
 idempotency_key uuid not null,
 organization_id uuid not null, branch_id uuid not null, client_id uuid not null,
 request_hash text not null check(request_hash ~ '^[a-f0-9]{64}$'),
 result_id uuid not null references private.taipei_abcd_draft_versions(id) on delete restrict,
 created_at timestamptz not null default clock_timestamp(),
 primary key(actor_user_id,idempotency_key)
);
create index taipei_abcd_operation_result_idx on private.taipei_abcd_draft_operations(result_id);
alter table private.taipei_abcd_draft_versions enable row level security;
alter table private.taipei_abcd_draft_versions force row level security;
alter table private.taipei_abcd_draft_operations enable row level security;
alter table private.taipei_abcd_draft_operations force row level security;
revoke all on private.taipei_abcd_draft_versions,private.taipei_abcd_draft_operations from public,anon,authenticated,service_role;
create trigger taipei_abcd_versions_immutable before update or delete on private.taipei_abcd_draft_versions
 for each row execute function private.abcd_assessment_history_is_append_only();
create trigger taipei_abcd_operations_immutable before update or delete on private.taipei_abcd_draft_operations
 for each row execute function private.abcd_assessment_history_is_append_only();
create trigger taipei_abcd_versions_audit after insert on private.taipei_abcd_draft_versions
 for each row execute function private.audit_row_change();

create function private.taipei_abcd_answers_valid(p_form text,p_answers jsonb) returns boolean
language plpgsql immutable security invoker set search_path='' as $$
declare e record; spec jsonb; s text; v jsonb; r jsonb; kind text; dt date;
begin
 if p_form not in ('A','B','C') or p_answers is null or jsonb_typeof(p_answers)<>'object' or octet_length(p_answers::text)>262144 then return false; end if;
 for e in select key,value from jsonb_each(p_answers) loop
  spec:=private.taipei_abcd_field_spec()->p_form->e.key;
  if spec is null or jsonb_typeof(e.value)<>'object' or not e.value ?& array['state','value','reason']
   or e.value-array['state','value','reason']<>'{}'::jsonb then return false; end if;
  s:=e.value->>'state'; v:=e.value->'value'; r:=e.value->'reason'; kind:=spec->>'kind';
  if s is null or s not in ('missing','not_applicable','recorded','unconfirmed') then return false; end if;
  if s in ('missing','not_applicable') then
   if v<>'null'::jsonb or (s='not_applicable' and r='null'::jsonb) or
    (r<>'null'::jsonb and (jsonb_typeof(r)<>'string' or char_length(r#>>'{}') not between 1 and 1000
     or btrim(r#>>'{}')<>r#>>'{}' or translate(r#>>'{}',E'\n\r\t','') ~ '[[:cntrl:]]')) then return false; end if;
  else
   if r<>'null'::jsonb or (s='unconfirmed' and not (spec->>'prefillAllowed')::boolean) then return false; end if;
   if kind='number' then
    if jsonb_typeof(v)<>'number' or (v#>>'{}')::numeric<(spec->>'min')::numeric or (v#>>'{}')::numeric>(spec->>'max')::numeric then return false; end if;
   elsif kind='multi' then
    if jsonb_typeof(v)<>'array' or jsonb_array_length(v)=0 then return false; end if;
    if exists(select 1 from jsonb_array_elements(v) x where jsonb_typeof(x)<>'string' or not (spec->'options') @> jsonb_build_array(x))
     or (select count(*)<>count(distinct x) from jsonb_array_elements(v) x) then return false; end if;
   else
    if jsonb_typeof(v)<>'string' or char_length(v#>>'{}') not between 1 and 4000 or btrim(v#>>'{}')<>v#>>'{}'
      or translate(v#>>'{}',E'\n\r\t','') ~ '[[:cntrl:]]' then return false; end if;
    if kind='choice' and not (spec->'options') @> jsonb_build_array(v) then return false; end if;
    if kind='date' then
     if (v#>>'{}') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then return false; end if;
     begin dt:=(v#>>'{}')::date; exception when others then return false; end;
     if dt::text<>v#>>'{}' or dt<'1900-01-01'::date or dt>'2200-12-31'::date then return false; end if;
    end if;
   end if;
  end if;
 end loop;
 return true;
end; $$;

create function private.taipei_abcd_require_scope(p_org uuid,p_branch uuid,p_client uuid,p_form text,p_write boolean)
returns void language plpgsql stable security definer set search_path='' as $$
begin
 if auth.uid() is null or not private.abcd_assessment_client_authority(p_org,p_branch,p_client,'abcd_assessments.read')
  or (p_write and not private.abcd_assessment_client_authority(p_org,p_branch,p_client,'abcd_assessments.manage'))
  -- A carries birthday, addresses and family contacts. Assessment permission
  -- must not bypass a separately revoked demographic field grant.
  or (p_form='A' and not private.can_staff_access_client(p_client,'clients.demographics.read'))
  or (p_form='C' and (not private.can_staff_access_client(p_client,'health.read') or not private.can_staff_access_client(p_client,'care_records.read'))) then
  raise exception using errcode='42501',message='Taipei ABC draft scope denied';
 end if;
end; $$;

create function private.taipei_abcd_month_sources(p_org uuid,p_branch uuid,p_client uuid,p_year integer,p_month integer)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare start_at timestamptz; end_at timestamptz; measurements jsonb; records jsonb;
begin
 perform private.taipei_abcd_require_scope(p_org,p_branch,p_client,'C',false);
 if p_year<>115 or p_month is null or p_month not between 1 and 12 then raise exception using errcode='22023',message='Invalid Taipei ABC month'; end if;
 start_at:=make_date(p_year+1911,p_month,1)::timestamp at time zone 'Asia/Taipei';
 end_at:=(make_date(p_year+1911,p_month,1)+interval '1 month') at time zone 'Asia/Taipei';
 select coalesce(jsonb_agg(jsonb_build_object('id',m.id,'measuredAt',m.measured_at,'kind',m.measurement_kind,
  'numericValue',m.numeric_value,'textValue',m.text_value,'unit',m.unit,'recordedBy',m.recorded_by) order by m.measured_at,m.id),'[]'::jsonb)
 into measurements from public.measurements m where m.organization_id=p_org and m.branch_id=p_branch and m.client_id=p_client
  and m.measured_at>=start_at and m.measured_at<end_at and m.source='staff'
  and m.measurement_kind in ('temperature','pulse','respiratory_rate','blood_pressure_systolic','blood_pressure_diastolic','weight');
 select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'version',r.version,'occurredAt',r.occurred_at,
  'contentHash',r.content_hash,'recordedBy',r.created_by,
  'data',jsonb_build_object('care_item',r.data->'fields'->'care_item','note',r.data->'fields'->'note','shift',r.data->'fields'->'shift',
     'abnormal',r.data->'fields'->'abnormal')) order by r.occurred_at,r.id),'[]'::jsonb)
 into records from public.care_records r where r.organization_id=p_org and r.branch_id=p_branch and r.client_id=p_client
  and r.occurred_at>=start_at and r.occurred_at<end_at and r.category='staff/daily-care/care-diary' and r.source_system='local'
  and r.status='signed' and r.signed_at is not null and r.signed_by is not null and r.content_hash is not null
  and not exists(select 1 from public.care_records newer where newer.organization_id=r.organization_id and newer.record_key=r.record_key and newer.version>r.version);
 if jsonb_array_length(measurements)>10000 or jsonb_array_length(records)>10000 then
  raise exception using errcode='54000',message='Monthly source limit reached'; end if;
 return jsonb_build_object('capturedAt',clock_timestamp(),'measurements',measurements,'careRecords',records,'healthAccess',true,'careAccess',true);
end; $$;

create function private.taipei_abcd_draft_json(r private.taipei_abcd_draft_versions) returns jsonb
language sql immutable security invoker set search_path='' as $$
 select jsonb_build_object('id',r.id,'organizationId',r.organization_id,'branchId',r.branch_id,'clientId',r.client_id,
  'form',r.form,'usageYear',r.usage_year,'month',r.month,'version',r.version,'previousVersionId',r.previous_version_id,
  'contentHash',r.content_hash,'answers',r.answers,'sourceSnapshot',r.source_snapshot,'createdAt',r.created_at,
  'publicationStatus',r.publication_status,'state',r.state);
$$;

create function private.taipei_abcd_draft_snapshot(p_org uuid,p_branch uuid,p_client uuid,p_form text,p_year integer,p_month integer)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare latest private.taipei_abcd_draft_versions%rowtype; history jsonb; sources jsonb;
begin
 perform private.taipei_abcd_require_scope(p_org,p_branch,p_client,p_form,false);
 if p_form is null or p_form not in ('A','B','C') or p_year is null or p_year<>115 or p_month is null
  or (p_form='C' and p_month not between 1 and 12) or (p_form<>'C' and p_month<>0) then
  raise exception using errcode='22023',message='Invalid Taipei ABC identity'; end if;
 select * into latest from private.taipei_abcd_draft_versions r where r.organization_id=p_org and r.branch_id=p_branch
  and r.client_id=p_client and r.form=p_form and r.usage_year=p_year and r.month=p_month order by r.version desc limit 1;
 select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'version',r.version,'createdAt',r.created_at) order by r.version desc),'[]'::jsonb)
 into history from private.taipei_abcd_draft_versions r where r.organization_id=p_org and r.branch_id=p_branch
  and r.client_id=p_client and r.form=p_form and r.usage_year=p_year and r.month=p_month;
 if p_form='C' then sources:=private.taipei_abcd_month_sources(p_org,p_branch,p_client,p_year,p_month); end if;
 insert into public.audit_events(organization_id,branch_id,actor_user_id,action,table_name,metadata)
 values(p_org,p_branch,auth.uid(),'select','private.taipei_abcd_draft_versions',jsonb_build_object('operation','taipei_draft_read','form',p_form,'usage_year',p_year,'month',p_month,'answers_logged',false));
 return jsonb_build_object('organizationId',p_org,'branchId',p_branch,'clientId',p_client,'form',p_form,'usageYear',p_year,'month',p_month,
 'latest',case when latest.id is null then null else private.taipei_abcd_draft_json(latest) end,'history',history,'currentSources',sources,
 'canEdit',private.abcd_assessment_client_authority(p_org,p_branch,p_client,'abcd_assessments.manage'));
end; $$;

create function private.save_taipei_abcd_draft(p_org uuid,p_branch uuid,p_payload jsonb,p_key uuid)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare actor uuid:=auth.uid(); client uuid; f text; yr integer; mon integer; expected integer; request_hash text;
 old private.taipei_abcd_draft_versions%rowtype; result private.taipei_abcd_draft_versions%rowtype;
 operation private.taipei_abcd_draft_operations%rowtype; sources jsonb;
begin
 if actor is null or p_key is null then raise exception using errcode='42501',message='Taipei ABC draft scope denied'; end if;
 if jsonb_typeof(p_payload) is distinct from 'object' or not p_payload ?& array['client_id','form','usage_year','month','template_key','source_revision','source_sha256','expected_version','expected_content_hash','answers','idempotency_key']
  or p_payload-array['client_id','form','usage_year','month','template_key','source_revision','source_sha256','expected_version','expected_content_hash','answers','idempotency_key']<>'{}'::jsonb then
  raise exception using errcode='22023',message='Invalid Taipei ABC draft'; end if;
 client:=(p_payload->>'client_id')::uuid; f:=p_payload->>'form'; yr:=(p_payload->>'usage_year')::integer;
 mon:=(p_payload->>'month')::integer; expected:=(p_payload->>'expected_version')::integer;
 perform private.taipei_abcd_require_scope(p_org,p_branch,client,f,true);
 if client is null or f is null or f not in ('A','B','C') or yr is null or yr<>115 or mon is null or
  (f='C' and mon not between 1 and 12) or (f<>'C' and mon<>0)
  or p_payload->>'template_key' is distinct from 'taipei.daycare.abcd.115.114-11.draft-v1'
  or p_payload->>'source_revision' is distinct from '114.11'
  or p_payload->>'source_sha256' is distinct from '64bb716b19362580295fe8ee2e452d32e82d6f3c67773d5956f66c7e17d3c481'
  or (p_payload->>'idempotency_key')::uuid is distinct from p_key
  or expected is null or expected not between 0 and 100000
  or not private.taipei_abcd_answers_valid(f,p_payload->'answers') then
  raise exception using errcode='22023',message='Invalid Taipei ABC draft'; end if;
 request_hash:=encode(sha256(convert_to(jsonb_build_object('organization',p_org,'branch',p_branch,'payload',p_payload)::text,'UTF8')),'hex');
 perform pg_advisory_xact_lock(hashtextextended('taipei-abcd-key:'||actor::text||':'||p_key::text,0));
 select * into operation from private.taipei_abcd_draft_operations o where o.actor_user_id=actor and o.idempotency_key=p_key;
 if operation.result_id is not null then
  if operation.request_hash<>request_hash then raise exception using errcode='23505',message='Taipei ABC idempotency conflict'; end if;
  select * into strict result from private.taipei_abcd_draft_versions where id=operation.result_id;
  return jsonb_build_object('draft',private.taipei_abcd_draft_json(result),'idempotencyKey',p_key,'replayed',true);
 end if;
 perform pg_advisory_xact_lock(hashtextextended('taipei-abcd-chain:'||p_org::text||':'||p_branch::text||':'||client::text||':'||f||':'||yr::text||':'||mon::text,0));
 select * into old from private.taipei_abcd_draft_versions r where r.organization_id=p_org and r.branch_id=p_branch
  and r.client_id=client and r.form=f and r.usage_year=yr and r.month=mon order by r.version desc limit 1;
 if coalesce(old.version,0)<>expected or old.content_hash is distinct from p_payload->>'expected_content_hash' then
  raise exception using errcode='40001',message='Taipei ABC version conflict'; end if;
 if f='C' then sources:=private.taipei_abcd_month_sources(p_org,p_branch,client,yr,mon); end if;
 insert into private.taipei_abcd_draft_versions(organization_id,branch_id,client_id,form,usage_year,month,template_key,source_revision,source_sha256,
  version,previous_version_id,answers,source_snapshot,content_hash,actor_user_id)
 values(p_org,p_branch,client,f,yr,mon,p_payload->>'template_key',p_payload->>'source_revision',p_payload->>'source_sha256',
  expected+1,old.id,p_payload->'answers',sources,encode(sha256(convert_to(jsonb_build_object('payload',p_payload,'sources',sources,'version',expected+1)::text,'UTF8')),'hex'),actor)
 returning * into result;
 insert into private.taipei_abcd_draft_operations(actor_user_id,idempotency_key,organization_id,branch_id,client_id,request_hash,result_id)
 values(actor,p_key,p_org,p_branch,client,request_hash,result.id);
 perform private.taipei_abcd_require_scope(p_org,p_branch,client,f,true);
 return jsonb_build_object('draft',private.taipei_abcd_draft_json(result),'idempotencyKey',p_key,'replayed',false);
end; $$;

create function public.taipei_abcd_draft_snapshot(p_expected_organization_id uuid,p_expected_branch_id uuid,p_client_id uuid,p_form text,p_usage_year integer,p_month integer)
returns jsonb language sql volatile security invoker set search_path='' as $$
 select private.taipei_abcd_draft_snapshot(p_expected_organization_id,p_expected_branch_id,p_client_id,p_form,p_usage_year,p_month);
$$;
create function public.save_taipei_abcd_draft(p_expected_organization_id uuid,p_expected_branch_id uuid,p_payload jsonb,p_idempotency_key uuid)
returns jsonb language sql volatile security invoker set search_path='' as $$
 select private.save_taipei_abcd_draft(p_expected_organization_id,p_expected_branch_id,p_payload,p_idempotency_key);
$$;
revoke all on function private.taipei_abcd_field_spec(),private.taipei_abcd_answers_valid(text,jsonb),
 private.taipei_abcd_require_scope(uuid,uuid,uuid,text,boolean),private.taipei_abcd_month_sources(uuid,uuid,uuid,integer,integer),
 private.taipei_abcd_draft_json(private.taipei_abcd_draft_versions),private.taipei_abcd_draft_snapshot(uuid,uuid,uuid,text,integer,integer),
 private.save_taipei_abcd_draft(uuid,uuid,jsonb,uuid),public.taipei_abcd_draft_snapshot(uuid,uuid,uuid,text,integer,integer),
 public.save_taipei_abcd_draft(uuid,uuid,jsonb,uuid) from public,anon,authenticated,service_role;
grant execute on function private.taipei_abcd_draft_snapshot(uuid,uuid,uuid,text,integer,integer),
 private.save_taipei_abcd_draft(uuid,uuid,jsonb,uuid),public.taipei_abcd_draft_snapshot(uuid,uuid,uuid,text,integer,integer),
 public.save_taipei_abcd_draft(uuid,uuid,jsonb,uuid) to authenticated;
commit;
